#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        sum += x;
    }

    long long r = (sum % n + n) % n;
    
    long long ans = min(r, (long long)n - r);
    
    cout << ans << "\n";

    return 0;
}
